
const fs = require('fs');
const path = require('path');
const icon192 = '';
const icon512 = '';
const distPath = path.join(__dirname, 'dist');
if (!fs.existsSync(distPath)) fs.mkdirSync(distPath, { recursive: true });
fs.writeFileSync(path.join(distPath, 'icon-192x192.png'), Buffer.from(icon192, 'base64'));
fs.writeFileSync(path.join(distPath, 'icon-512x512.png'), Buffer.from(icon512, 'base64'));
console.log('Icons written to dist/ successfully.');
